-- Патч 27.11.2026 (5): новые фото Republique (чёрный и серый меланж; белый — прежние фото из каталога). Только один раз — можно запускать повторно.
update public.products set data = jsonb_set(data, '{photos}', '[{"src": "img/republique_black_1.jpg", "color": "Чёрный"}, {"src": "img/republique_black_2.jpg", "color": "Чёрный"}, {"src": "img/republique_black_3.jpg", "color": "Чёрный"}, {"src": "img/republique_black_4.jpg", "color": "Чёрный"}, {"src": "img/republique_black_5.jpg", "color": "Чёрный"}, {"src": "img/republique_black_6.jpg", "color": "Чёрный"}, {"src": "img/republique_black_7.jpg", "color": "Чёрный"}, {"src": "img/republique_grey_1.jpg", "color": "Серый меланж"}, {"src": "img/republique_grey_2.jpg", "color": "Серый меланж"}, {"src": "img/republique_grey_3.jpg", "color": "Серый меланж"}, {"src": "img/republique_grey_4.jpg", "color": "Серый меланж"}, {"src": "img/republique_grey_5.jpg", "color": "Серый меланж"}, {"src": "img/republique_grey_6.jpg", "color": "Серый меланж"}, {"src": "img/p38_0.jpg", "color": "Белый"}, {"src": "img/p38_3.jpg", "color": "Белый"}]'::jsonb) where id = 'republique' and (data->'photos')::text not like '%republique_%' and (data->'photos')::text like '%p38_1%';
select id, jsonb_array_length(data->'photos') as фото from public.products where id in ('alou', 'infinity', 'luna', 'republique', 'valencia', 'yosh') order by id;
